  m={t:'png',s:seat,x:Math.round(x),y:Math.round(y),w:netClean(it.name,24),pl:1};
  for(i=0;i<NET.peers.length;i++){ pe=NET.peers[i]; if(pe.state!=='in'||pe.seat===seat) continue; if(netSend(pe,m)) n++; }
